<?php

namespace Database\Seeders\Helpers;

use App\Models\Course;
use App\Models\Lesson;

class SectionOfficerQuizBank
{
    public static function attachQuestionsToAllLessons(Course $course): void
    {
        $moduleIds = $course->modules()->pluck('id')->toArray();
        $lessons = Lesson::where(function ($query) use ($moduleIds, $course) {
            $query->whereIn('module_id', $moduleIds)
                ->orWhereHas('chapter.module', function ($q) use ($course) {
                    $q->where('course_id', $course->id);
                });
        })->get();

        foreach ($lessons as $lesson) {
            $questions = self::getQuestionsForLesson($lesson->title);

            $lesson->quiz_questions = $questions;
            if ($lesson->type === 'quiz') {
                $lesson->content = json_encode($questions, JSON_UNESCAPED_UNICODE);
            }
            $lesson->save();
        }
    }

    public static function getQuestionsForLesson(string $title): array
    {
        $key = strtolower($title);

        // Module 1: General Awareness
        if (str_contains($key, 'geography')) {
            return self::qGeography();
        }
        if (str_contains($key, 'history') || str_contains($key, 'culture and socio-political')) {
            return self::qHistoryCulture();
        }
        if (str_contains($key, 'constitution of nepal') || str_contains($key, 'political systems')) {
            return self::qPolityConstitution();
        }
        if (str_contains($key, 'economic development') || str_contains($key, 'planning')) {
            return self::qEconomyPlanning();
        }
        if (str_contains($key, 'sustainable development') || str_contains($key, 'biodiversity') || str_contains($key, 'climate')) {
            return self::qEnvironmentClimate();
        }
        if (str_contains($key, 'science') || str_contains($key, 'international relations') || str_contains($key, 'multilateralism')) {
            return self::qScienceInternational();
        }

        // Module 2: Aptitude Test & Reasoning
        if (str_contains($key, 'verbal reasoning')) {
            return self::qVerbalReasoning();
        }
        if (str_contains($key, 'analytical reasoning') || str_contains($key, 'assertion-reason')) {
            return self::qAnalyticalReasoning();
        }
        if (str_contains($key, 'non-verbal reasoning') || str_contains($key, 'spatial')) {
            return self::qNonVerbalReasoning();
        }
        if (str_contains($key, 'quantitative aptitude') || str_contains($key, 'numerical')) {
            return self::qQuantitativeAptitude();
        }
        if (str_contains($key, 'data interpretation') || str_contains($key, 'data sufficiency')) {
            return self::qDataInterpretation();
        }

        // Module 3: English Language Competence
        if (str_contains($key, 'reading comprehension')) {
            return self::qReadingComprehension();
        }
        if (str_contains($key, 'vocabulary') || str_contains($key, 'synonyms')) {
            return self::qVocabulary();
        }
        if (str_contains($key, 'idiomatic') || str_contains($key, 'phrasal verbs')) {
            return self::qIdiomsPhrasal();
        }
        if (str_contains($key, 'syntactic ability') || str_contains($key, 'agreement')) {
            return self::qSyntaxAgreement();
        }
        if (str_contains($key, 'transformations') || str_contains($key, 'voice') || str_contains($key, 'speech')) {
            return self::qGrammarTransformations();
        }

        // Module 4: Governance Systems
        if (str_contains($key, 'state, nation-building') || str_contains($key, 'constitutionalism')) {
            return self::qStateGovernance();
        }
        if (str_contains($key, 'federal governance') || str_contains($key, 'inter-governmental')) {
            return self::qFederalGovernance();
        }
        if (str_contains($key, 'public administration') || str_contains($key, 'administrative reform')) {
            return self::qPublicAdminReform();
        }
        if (str_contains($key, 'ethics') || str_contains($key, 'accountability') || str_contains($key, 'integrity')) {
            return self::qEthicsAccountability();
        }
        if (str_contains($key, 'e-governance') || str_contains($key, 'public policy')) {
            return self::qPolicyEgov();
        }

        // Module 5: Contemporary Issues
        if (str_contains($key, 'social justice') || str_contains($key, 'human rights') || str_contains($key, 'demographic')) {
            return self::qSocialIssues();
        }
        if (str_contains($key, 'macroeconomic') || str_contains($key, 'public finance')) {
            return self::qMacroFinance();
        }
        if (str_contains($key, 'sectoral economic growth') || str_contains($key, 'tourism')) {
            return self::qSectoralGrowth();
        }
        if (str_contains($key, 'climate vulnerability') || str_contains($key, 'disaster management')) {
            return self::qDisasterClimate();
        }
        if (str_contains($key, 'national security') || str_contains($key, 'geopolitics') || str_contains($key, 'foreign policy')) {
            return self::qForeignSecurity();
        }

        // Module 6: Service Related Administration & Law
        if (str_contains($key, 'civil service act')) {
            return self::qCivilServiceAct();
        }
        if (str_contains($key, 'administrative law') || str_contains($key, 'delegation')) {
            return self::qAdminLaw();
        }
        if (str_contains($key, 'public procurement management')) {
            return self::qProcurementManagement();
        }
        if (str_contains($key, 'financial procedures') || str_contains($key, 'fiscal responsibility')) {
            return self::qFiscalProcedures();
        }
        if (str_contains($key, 'office management') || str_contains($key, 'decision making') || str_contains($key, 'tippani')) {
            return self::qOfficeDecisionTippani();
        }

        return self::qOfficerGeneralAssessment();
    }

